# GS/pages/ui.R  --  The GS user interface: the folders, the Standard pages and ui.
# Sourced by app.R at the top level (local = TRUE); the Workbench (workbench/wb_gs.R) reuses these pages.

if (dir.exists(file.path(APP_DIR, "docs"))) addResourcePath("docs", file.path(APP_DIR, "docs"))
# The folders (Settings in the Standard interface, Import data in the Workbench).
std_folders <- function() tagList(
  textAreaInput("set_raw", "Raw ERT archive (one folder per line; read only)", paste(CFG$raw_dirs, collapse = "\n"), rows = 3, width = "100%"), ovid_browse_button("set_raw"),
  textInput("set_project", "Project folder (catalogue, metadata and settings are kept here)", CFG$project_dir, width = "100%"), ovid_browse_button("set_project"))
# The Standard pages: the tools and section labels for ovid_page(), in rail order. The Workbench shows the same pages in
# its own frame (workbench/wb_gs.R); there sources = FALSE leaves the folders and Scan off Home, as its Import data
# view holds them.
std_pages <- function(sources = TRUE) list(
  "Catalogue",
  ovid_tool("Home", icon = "house",                                 # GS/pages/mod_home.R: the folders and Scan, and counts of what the scan found
    mod_home_ui("home", if (sources) tagList(std_folders(), actionButton("rebuild", "Scan the archive", class = "btn-primary"),
      p(class = "muted mt-2", "Scanning reads new and changed files and keeps everything people entered; the raw files are never changed.")))),
  ovid_tool("Archive", icon = "box-archive",
    div(class = "panel-x", group_by_ui("gb")),                       # grouped by instrument or aircraft, stay, download or file (core grouping.R)
    mod_archive_ui("archive", sidebar_extra = tagList(                 # GS/pages/mod_archive.R
      hr(), fileInput("cat_import", "Open a catalogue (zip)", accept = ".zip"),
      checkboxInput("x_meas", "Include measurements", FALSE),
      downloadButton("dl_archive", "Export catalogue (ZIP)", class = "btn-primary w-100"),
      p(class = "muted mt-1", "A zip others can open without the raw files: index.html, the tables, previews and metadata.")))),
  ovid_tool("Stack", icon = "bars-staggered", mod_stack_ui("stack")),   # GS/pages/mod_stack.R: a project's surveys side by side
  ovid_tool("Map", icon = "map-location-dot",
    ovid_controls(
      selectizeInput("map_years", "Survey years", choices = NULL, multiple = TRUE, options = list(plugins = list("remove_button"), placeholder = "All years"), width = "300px"),
      selectizeInput("map_projects", "Projects", choices = NULL, multiple = TRUE, options = list(plugins = list("remove_button"), placeholder = "All projects"), width = "300px"),
      ovid_split_toggle("map_split", "Map and transect details"),
      checkboxInput("map_legend", "Legend", TRUE),
      tags$button(class = "btn btn-sm btn-outline-secondary", onclick = "ovidPlotPng('map', $('#map_legend').is(':checked'), 'map')", "Export view (PNG)"),   # with the legend when Legend is ticked
      tags$script(HTML(MAP_PNG_JS)),
      more = tagList(radioButtons("map_base", "Map", c(Satellite = "satellite", Streets = "streets"), inline = TRUE),
                     p(class = "muted", "Green: start, red: end. Click a year in the legend to hide it."),
                     p(class = "muted", "Latitude and longitude in decimal degrees (WGS84). Satellite imagery: Esri World Imagery; streets: OpenStreetMap. Both need an internet connection.")),
      more_label = "Map layers"),
    uiOutput("map_empty"),                                             # surveys not placed: Import coordinates (pages/map_and_transects.R)
    ovid_split("map_split", width = "32%",
      ovid_focus(plotly::plotlyOutput("map", height = "620px", fill = FALSE)),
      card(card_header("Transect details"),
        selectInput("t_pick", "Transect", choices = NULL),
        layout_columns(col_widths = c(6, 6), textInput("t_id", "Transect id"), textInput("t_name", "Name")),
        textInput("t_site", "Site"),
        textInput("t_start", "Start point (lat, lon)", placeholder = "45.5000, -72.2000"),
        textInput("t_end", "End point (lat, lon)", placeholder = "45.5002, -72.1985"),
        uiOutput("t_geom"),
        selectizeInput("t_surveys", "Surveys on this transect", choices = NULL, multiple = TRUE),
        textAreaInput("t_notes", "Notes", rows = 2),
        actionButton("t_save", "Save transect", class = "btn-primary w-100"),
        p(class = "muted mt-2", "Saved to config/transects.csv; the surveys picked are linked to this transect in config/surveys.csv. Points accept decimal degrees or 61\u00b018\u203232\u2033N 121\u00b018\u203216\u2033W."))),
    card(card_header("Transects"),
      p(class = "muted mb-1", "Follows the year and project choices above the map. Click a row to edit that transect."), DTOutput("t_table"))),
  "GPR",
  ovid_tool("Map", value = "GPR", icon = "layer-group",
    uiOutput("gpr_empty"),                                             # no line yet: what to do (the GPR side's empty state)
    p(class = "muted mt-3", "MALA ground-penetrating radar lines: the .rad header, the .rd3 or .rd7 traces and the .cor GPS positions are put together from what the header says, wherever they sit in these folders. Viewing only; nothing is changed or catalogued."),
    mod_gpr_map_ui("gprmap"),                                          # GS/pages/mod_gpr_map.R: the tracks, the line table, a shared cursor
    card(id = "gpr-folders", style = "max-width:900px", card_header("GPR folders"),
      textAreaInput("gpr_dirs", "Folders to search (one per line; read only)", paste(SETTINGS$gpr_dirs %||% CFG$raw_dirs, collapse = "\n"), rows = 2, width = "100%"), ovid_browse_button("gpr_dirs"),
      div(class = "d-flex gap-2 align-items-center", actionButton("gpr_rescan", "Search again", class = "btn-sm btn-outline-secondary"), uiOutput("gpr_sum", inline = TRUE))),
    card(card_header("All lines found"), DTOutput("gpr_table"))),
  ovid_tool("Processing", value = "GPR processing", icon = "sliders",
    mod_gpr_flow_ui("gprflow", wb = !sources)),                        # GS/pages/mod_gpr_flow.R: one screen for both interfaces
  "Survey",
  ovid_tool("Survey", icon = "wave-square",
    ovid_controls(tagAppendAttributes(selectInput("survey", "Survey", choices = NULL, width = "100%"), class = "d-wide"),
                    ovid_split_toggle("sv_split", "Survey and details")),
    uiOutput("survey_head"),
    ovid_split("sv_split", width = "32%",
      navset_card_tab(id = "view_tab",
        nav_panel("Pseudosection",
          div(class = "viewbar",
            selectInput("v_colour", "Colour by", setNames(VAR_INFO$var, sub(", log\\)", ")", VAR_INFO$label)), width = "240px"),
            radioButtons("v_show", "Show", c(All = "all", Passed = "passed", Flagged = "flagged"), inline = TRUE),
            div(class = "ms-auto", popover(actionButton("v_opts", "Display options", icon = icon("sliders"), class = "btn-sm btn-outline-primary"),
              title = "Display", placement = "left",
              selectInput("v_pal", "Colours", names(PALETTES)),
              radioButtons("v_scale", "Colour scale", c(Log = "log", Linear = "linear"), inline = TRUE),
              div(class = "d-flex gap-2", numericInput("v_min", "Resistivity min (ohm-m)", RHOA_RANGE[1], min = 0, width = "50%"), numericInput("v_max", "Resistivity max (ohm-m)", RHOA_RANGE[2], min = 1, width = "50%"))))),
          ovid_focus(uiOutput("pseudo_area")),
          p(class = "muted", "Hover a point for its values; drag to zoom, double-click to reset. Pseudo-depth = 0.19 x array length.")),
        nav_panel("Distributions", ovid_focus(plotly::plotlyOutput("survey_hist", height = "620px", fill = FALSE)),
                  p(class = "muted", "Uses the Colour by and colour scale settings of the pseudosection (Display options).")),
        nav_panel("Contact", ovid_focus(plotly::plotlyOutput("survey_contact", height = "620px", fill = FALSE)),
                  p(class = "muted", "Each current injection's A-B resistance at both electrodes. Dotted guides at 2, 5 and 10 kohm (EarthImager manual, 3.5.9).")),
        nav_panel("Error vs current", ovid_focus(plotly::plotlyOutput("survey_errcur", height = "620px", fill = FALSE)),
                  p(class = "muted", "Error model for inversion (written with the survey's export, inversion/): ", textOutput("survey_errmodel", inline = TRUE))),
        nav_panel("Geometry", ovid_focus(plotly::plotlyOutput("survey_geom", height = "430px", fill = FALSE)),
          p(class = "muted", "Gold: electrodes after a gap in the spacing. Elevation is in metres (linear)."),
          div(class = "d-flex gap-3 align-items-end flex-wrap",
            fileInput("elev_file", "Add elevations for this survey (CSV or GNSS file)", accept = c(".csv", ".txt"), width = "340px"),
            actionButton("elev_clear", "Remove this survey's elevations", class = "btn-sm btn-outline-secondary mb-3")),
          p(class = "muted", "An elevation table has the columns electrode and elevation (one row per electrode), or distance and elevation along the line (interpolated to every electrode).",
            "A GNSS file (an Emlid, Leica or DJI export, or the RS app's GNSS points) needs a point name and an elevation: the electrode is the last number in each name (E12, T1-E12, 12).",
            "Saved to config/elevations.csv; the measurements as read are kept.")),
        nav_panel("Data", DTOutput("survey_table", fill = TRUE)),
        nav_panel("Details", div(style = "overflow-y:auto", uiOutput("survey_about")))),
      div(card(card_header("Edit survey"),
               div(class = "d-flex gap-2 align-items-end", selectInput("dl_profile", "QC profile", choices = NULL, width = "200px"),
                   downloadButton("dl_survey", "Export survey (ZIP)", class = "btn-sm btn-outline-primary mb-3")),
               accordion(open = "Survey", multiple = FALSE,
                 accordion_panel("Survey", textInput("m_name", "Name"), suppressWarnings(dateInput("m_date", "Date acquired", value = NA)),   # NA: empty until a survey is picked; shiny warns about it but draws it empty
                                 textInput("m_operator", "Operator"), textInput("m_instrument", "Instrument (correct it if the files are wrong)")),
                 accordion_panel("Where", textInput("m_project", "Project"), textInput("m_site", "Site"), uiOutput("m_transect")),   # the transect is set on the Map or in Archive
                 accordion_panel("Conditions", textInput("m_conditions", "Weather and season"), textInput("m_ground", "Ground (frozen, snow, wet ...)")),
                 accordion_panel("Quality", selectInput("m_quality", "Survey quality", names(QUALITY_COL)),
                                 selectizeInput("m_reasons", "Reasons", QUALITY_REASONS, multiple = TRUE), textAreaInput("m_qnotes", "Quality notes", rows = 2)),
                 accordion_panel("Processing and reporting", textInput("m_contact", "Electrode contact (e.g. salt water added, frozen ground)"), uiOutput("survey_checklist")),
                 accordion_panel("Notes", textAreaInput("m_notes", NULL, rows = 4))),
               actionButton("m_save", "Save details", class = "btn-primary w-100 mt-2")),
          card(card_header("Files"), uiOutput("survey_files"))))),
  ovid_tool("QC", icon = "filter",
    layout_sidebar(fillable = FALSE,
      sidebar = sidebar(width = 360, title = "Limits",
        selectInput("profile", "Start from profile", choices = NULL),
        uiOutput("profile_help"),
        accordion(open = c("Signal", "Contact"), multiple = TRUE,
          accordion_panel("Signal", lapply(which(SLIDERS$group == "Signal"), slider_row)),
          accordion_panel("Contact", lapply(which(SLIDERS$group == "Contact"), slider_row)),
          accordion_panel("Values", div(class = "d-flex align-items-start gap-2",
              div(style = "padding-top:28px", checkboxInput("on_rhoa_range", NULL, FALSE)),
              div(class = "flex-grow-1", sliderInput("v_rhoa_range", "Apparent resistivity (log10 ohm-m)", -1, 6, c(0, 5), step = 0.1, width = "100%"))),
            lapply(seq_len(nrow(TOGGLES)), function(i) checkboxInput(paste0("on_", TOGGLES$rule[i]), TOGGLES$label[i], FALSE))),
          accordion_panel("Checks", lapply(which(SLIDERS$group == "Checks"), slider_row))),
        hr(), textInput("save_name", "Save as profile", "custom"),
        actionButton("save", "Save profile", class = "btn-primary w-100"),
        p(class = "muted mt-2", "Sliders never change measurements; saving adds the profile to config/qc_profiles.csv.")),
      ovid_controls(tagAppendAttributes(selectInput("qc_survey", "Survey", choices = NULL, width = "100%"), class = "d-wide")),
      uiOutput("qc_summary"),
      card(card_header("Pseudosection", span(class = "muted float-end", "colour and display options are on the Survey page")), ovid_focus(plotly::plotlyOutput("qc_plot", height = "600px"))),
      card(card_header("Flags by rule"), DTOutput("qc_flags")),
      card(card_header("Electrodes turned off in this survey"),
        p(class = "muted", "Measurements using an electrode that was turned off are flagged, in every profile, and the electrode is marked off in electrodes.csv. Saved in config/electrode_status.csv."),
        radioButtons("eo_scope", NULL, c(`In this survey` = "survey", `In every survey on its transect in a period` = "transect"), inline = TRUE),
        conditionalPanel("input.eo_scope == 'transect'", div(class = "d-flex gap-2 align-items-end",
          textInput("eo_from", "From (blank: from the start)", "", width = "200px", placeholder = "2024-08-31"),
          textInput("eo_to", "To (blank: to now)", "", width = "200px", placeholder = "2024-08-31"), uiOutput("eo_tr", inline = TRUE))),
        div(class = "d-flex gap-2 align-items-end", textInput("eo_list", "Electrodes (for example 12, 15-17)", "", width = "220px"), textInput("eo_reason", "Reason", "", width = "260px"),
            actionButton("eo_add", "Mark off", class = "btn-outline-primary")),
        DTOutput("eo_tbl"), actionButton("eo_clear", "Turn them all back on for this survey", class = "btn-outline-secondary mt-2")))),
  "Set-up",
  ovid_tool("Set-up tables", value = "Setup", icon = "table-list",
    p(class = "muted mt-3", "Everything people decide about the archive is kept in tables in config/ in the project folder, and this page edits every one of them; the Survey, Map and QC pages write some of them too. A saved change applies on the next scan, and each save keeps the version before it in config/history."),
    do.call(navset_card_tab, c(list(id = "setup_tab"), lapply(which(SETUP_TABLES$tab), function(i)      # every table with a tab (pages/utils_setup.R)
      nav_panel(SETUP_TABLES$file[i], value = SETUP_TABLES$id[i], p(class = "muted", SETUP_TABLES$help[i]), editUI(SETUP_TABLES$id[i])))))),
  "Help",
  convert_tool(), reference_tool("GS"),                                       # core reference.R (the guide as a searchable index)
  ovid_tool("Settings", icon = "sliders", rail = FALSE,
    card(class = "mt-3", style = "max-width:1100px", card_header("Time zone"), time_zone_ui(SETTINGS$base_offset_h %||% NA)),
    card(class = "mt-3", style = "max-width:1100px", card_header("Colours"), colours_ui()),
    card(class = "mt-3", style = "max-width:1100px", card_header("Projects"), projects_list_ui("proj")),
    card(class = "mt-3", style = "max-width:720px", card_header("QC profile of the catalogue"),
      selectInput("set_cat_profile", "Profile the catalogue reports (Kept %, previews, exports)", choices = NULL, width = "360px"),
      p(class = "muted", "Every profile in qc_profiles.csv is checked at each scan, the ones saved on the QC page too; this one fills the catalogue. A change applies at the next scan.")),
    card(class = "mt-3", style = "max-width:1100px", card_header("Set-up check and file audit"),
        div(class = "d-flex gap-2 align-items-center mb-2", uiOutput("chk_sum", inline = TRUE), span(class = "ms-auto"),
            actionButton("chk_run", "Check again", class = "btn-sm"), ovid_export_button("fa_dl", "csv", "file audit", class = "btn-sm")),
        DTOutput("chk_tbl"),
        p(class = "muted mt-2", "What in the set-up would be ignored, misapplied or is missing (nothing is changed). The file audit lists every raw file and what became of it; it is written by each scan.")))
)
# The two sides of GS (core shell.R ovid_areas_ui): resistivity and GPR. Set-up tables, Convert, Reference and Settings
# show on both.
GS_AREAS <- list(ERT = c("Home", "Archive", "Stack", "Map", "Survey", "QC"), GPR = c("GPR", "GPR processing"))
ui <- do.call(ovid_page, c(list("GS", PAL, theme = THEME, settings = "Settings", areas = GS_AREAS, project = projects_switch_ui("proj"),
  status = uiOutput("cat_path", inline = TRUE),
  actions = tags$a(class = "btn btn-outline-secondary btn-sm", href = "?ui=workbench", title = "Open the Workbench interface (preview) on this catalogue and survey",
                   onclick = "var s=$('#survey').val(); if(s){this.href='?ui=workbench&survey='+encodeURIComponent(s);}",
                   "Workbench", span(style = "font-size:10px;margin-left:4px;opacity:.8", "preview")),
  help = if (file.exists(file.path(APP_DIR, "docs", "GS_reference_guide.html"))) "docs/GS_reference_guide.html"), std_pages()))
